module max_executables (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr_0,\n    input wire [7:0] arr_1,\n    input wire [7:0] arr_2,\n    input wire [7:0] arr_3,\n    input wire [7:0] arr_4,\n    input wire [7:0] arr_5,\n    input wire [7:0] arr_6,\n    input wire [7:0] arr_7,\n    input wire [3:0] N,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_COMPUTE_PREFIX = 4'd1;\n    localparam [3:0] S_SET_BEST0 = 4'd2;\n    localparam [3:0] S_INIT_I = 4'd3;\n    localparam [3:0] S_LOOP_J_START = 4'd4;\n    localparam [3:0] S_COMPUTE_S = 4'd5;\n    localparam [3:0] S_COMPARE = 4'd6;\n    localparam [3:0] S_UPDATE = 4'd7;\n    localparam [3:0] S_NEXT_J = 4'd8;\n    localparam [3:0] S_NEXT_I = 4'd9;\n    localparam [3:0] S_DONE = 4'd10;\n\n    reg [3:0] state, next_state;\n\n    // Arrays\n    reg [31:0] prefix [0:8];\n    reg [7:0] best [0:7];\n    reg [31:0] sum [0:7];\n\n    // Temporary registers\n    reg [3:0] i_idx, j_idx;\n    reg [31:0] temp_s;\n    reg [7:0] candidate;\n    reg [31:0] temp_sum_reg;\n    reg [7:0] temp_best_reg;\n    reg [3:0] prefix_idx;\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            S_IDLE: begin\n                if (start)\n                    next_state = S_COMPUTE_PREFIX;\n            end\n            S_COMPUTE_PREFIX: begin\n                if (prefix_idx > N)\n                    next_state = S_SET_BEST0;\n            end\n            S_SET_BEST0: begin\n                next_state = S_INIT_I;\n            end\n            S_INIT_I: begin\n                next_state = S_LOOP_J_START;\n            end\n            S_LOOP_J_START: begin\n                next_state = S_COMPUTE_S;\n            end\n            S_COMPUTE_S: begin\n                next_state = S_COMPARE;\n            end\n            S_COMPARE: begin\n                if (temp_s >= sum[j_idx])\n                    next_state = S_UPDATE;\n                else\n                    next_state = S_NEXT_J;\n            end\n            S_UPDATE: begin\n                next_state = S_NEXT_J;\n            end\n            S_NEXT_J: begin\n                if (j_idx < i_idx)\n                    next_state = S_LOOP_J_START;\n                else\n                    next_state = S_NEXT_I;\n            end\n            S_NEXT_I: begin\n                if (i_idx < N - 1)\n                    next_state = S_INIT_I;\n                else\n                    next_state = S_DONE;\n            end\n            S_DONE: begin\n                if (!start)\n                    next_state = S_IDLE;\n            end\n            default: next_state = S_IDLE;\n        endcase\n    end\n\n    // Datapath\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset registers\n            prefix_idx <= 4'd0;\n            i_idx <= 4'd0;\n            j_idx <= 4'd0;\n            temp_s <= 32'd0;\n            candidate <= 8'd0;\n            temp_sum_reg <= 32'd0;\n            temp_best_reg <= 8'd0;\n            result <= 8'd0;\n            done <= 1'b0;\n            // Reset arrays\n            integer k;\n            for (k = 0; k < 9; k = k + 1) begin\n                prefix[k] <= 32'd0;\n            end\n            for (k = 0; k < 8; k = k + 1) begin\n                best[k] <= 8'd0;\n                sum[k] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        prefix_idx <= 4'd1;\n                        prefix[0] <= 32'd0;\n                    end\n                end\n                S_COMPUTE_PREFIX: begin\n                    if (prefix_idx <= N) begin\n                        case (prefix_idx)\n                            1: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_0;\n                            2: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_1;\n                            3: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_2;\n                            4: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_3;\n                            5: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_4;\n                            6: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_5;\n                            7: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_6;\n                            8: prefix[prefix_idx] <= prefix[prefix_idx - 1] + arr_7;\n                            default: prefix[prefix_idx] <= prefix[prefix_idx - 1];\n                        endcase\n                        prefix_idx <= prefix_idx + 4'd1;\n                    end\n                end\n                S_SET_BEST0: begin\n                    best[0] <= 8'd1;\n                    sum[0] <= prefix[1];\n                    i_idx <= 4'd1;\n                end\n                S_INIT_I: begin\n                    temp_best_reg <= 8'd1;\n                    temp_sum_reg <= prefix[i_idx + 1];\n                    j_idx <= 4'd0;\n                end\n                S_LOOP_J_START: begin\n                    // No operation\n                end\n                S_COMPUTE_S: begin\n                    case (i_idx)\n                        1: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        2: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        3: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        4: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        5: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        6: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        7: temp_s <= prefix[i_idx + 1] - prefix[j_idx + 1];\n                        default: temp_s <= 32'd0;\n                    endcase\n                end\n                S_COMPARE: begin\n                    // No operation\n                end\n                S_UPDATE: begin\n                    case (j_idx)\n                        0: candidate <= best[j_idx] + 8'd1;\n                        1: candidate <= best[j_idx] + 8'd1;\n                        2: candidate <= best[j_idx] + 8'd1;\n                        3: candidate <= best[j_idx] + 8'd1;\n                        4: candidate <= best[j_idx] + 8'd1;\n                        5: candidate <= best[j_idx] + 8'd1;\n                        6: candidate <= best[j_idx] + 8'd1;\n                        7: candidate <= best[j_idx] + 8'd1;\n                        default: candidate <= 8'd0;\n                    endcase\n                    if (candidate > temp_best_reg) begin\n                        temp_best_reg <= candidate;\n                        temp_sum_reg <= temp_s;\n                    end else if (candidate == temp_best_reg && temp_s < temp_sum_reg) begin\n                        temp_sum_reg <= temp_s;\n                    end\n                end\n                S_NEXT_J: begin\n                    j_idx <= j_idx + 4'd1;\n                end\n                S_NEXT_I: begin\n                    case (i_idx)\n                        1: best[i_idx] <= temp_best_reg;\n                        2: best[i_idx] <= temp_best_reg;\n                        3: best[i_idx] <= temp_best_reg;\n                        4: best[i_idx] <= temp_best_reg;\n                        5: best[i_idx] <= temp_best_reg;\n                        6: best[i_idx] <= temp_best_reg;\n                        7: best[i_idx] <= temp_best_reg;\n                        default: best[i_idx] <= 8'd0;\n                    endcase\n                    case (i_idx)\n                        1: sum[i_idx] <= temp_sum_reg;\n                        2: sum[i_idx] <= temp_sum_reg;\n                        3: sum[i_idx] <= temp_sum_reg;\n                        4: sum[i_idx] <= temp_sum_reg;\n                        5: sum[i_idx] <= temp_sum_reg;\n                        6: sum[i_idx] <= temp_sum_reg;\n                        7: sum[i_idx] <= temp_sum_reg;\n                        default: sum[i_idx] <= 32'd0;\n                    endcase\n                    i_idx <= i_idx + 4'd1;\n                end\n                S_DONE: begin\n                    case (N)\n                        1: result <= best[0];\n                        2: result <= best[1];\n                        3: result <= best[2];\n                        4: result <= best[3];\n                        5: result <= best[4];\n                        6: result <= best[5];\n                        7: result <= best[6];\n                        8: result <= best[7];\n                        default: result <= 8'd0;\n                    endcase\n                    done <= 1'b1;\n                end\n                default: begin\n                    // No operation\n                end\n            endcase\n        end\n    end\n\nendmodule